import React, { useState } from 'react';
import { signInWithEmailAndPassword } from 'firebase/auth';
import { auth } from '../firebase-config'; 

const LogIn = ({ onLogin, isOnline, apiBaseUrl }) => {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');

    const manejarSubmit = async (e) => {
        e.preventDefault();
        if (!isOnline) return; 

        try {
            const userCredential = await signInWithEmailAndPassword(auth, email, password);
            const user = userCredential.user;

            const response = await fetch(`${apiBaseUrl}/usuarios/login`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify({ email: user.email }),
            });

            if (response.ok) {
                const datosServidor = await response.json();
                onLogin(datosServidor); 
            }
        } catch (err) {
            setError("Error al entrar: revisa tus datos");
        }
    };

    return (
        /* He añadido bg-white y text-dark para que no se hereden los morados/blancos del fondo */
        <div className="card shadow-lg border-0 mt-3 bg-white text-dark" style={{ maxWidth: '400px', margin: 'auto' }}> 
            <div className="card-header bg-primary text-white text-center py-3">
                <h5 className="mb-0">Identificación</h5>
            </div>
            <div className="card-body p-4">
                <form onSubmit={manejarSubmit}>
                    {error && <div className="alert alert-danger p-2 small">{error}</div>}
                    
                    <div className="mb-3 text-start">
                        <label className="form-label small fw-bold text-dark">Email</label>
                        <input 
                            type="email" 
                            className="form-control border-secondary" 
                            style={{ color: '#000', backgroundColor: '#fff' }}
                            value={email}
                            onChange={(e) => setEmail(e.target.value)}
                            placeholder="tu@email.com"
                            required
                        />
                    </div>
                    <div className="mb-3 text-start">
                        <label className="form-label small fw-bold text-dark">Contraseña</label>
                        <input 
                            type="password" 
                            className="form-control border-secondary" 
                            style={{ color: '#000', backgroundColor: '#fff' }}
                            value={password}
                            onChange={(e) => setPassword(e.target.value)}
                            placeholder="********"
                            required
                        />
                    </div>
                    <button type="submit" className="btn btn-primary w-100 fw-bold shadow-sm mt-2" disabled={!isOnline}>
                        {isOnline ? "Entrar a la tienda" : "Sin conexión"}
                    </button>
                </form>
            </div>
        </div>
    );
}; 

export default LogIn;
